package e.e.a;
import java.net.*;import java.io.*;import java.util.*;
public class Mp4PlaylistTest{
 static int checks;static void check(boolean b){checks++;if(!b)throw new AssertionError("MP4 check "+checks);}interface Bad{void run()throws Exception;}static void bad(Bad b)throws Exception{boolean failed=false;try{b.run();}catch(IOException e){failed=true;}check(failed);}
 public static void main(String[] args)throws Exception{URL base=new URL("https://delivery.domand.nicovideo.jp/a/video.m3u8");String ending="\n#EXT-X-ENDLIST\n";
 Mp4Playlist115.Plan p=Mp4Playlist115.parse(base,"#EXTM3U\n#EXT-X-MAP:URI=\"init.mp4\",BYTERANGE=\"100@0\"\n#EXT-X-MEDIA-SEQUENCE:42\n#EXT-X-KEY:METHOD=AES-128,URI=\"key\"\n#EXT-X-BYTERANGE:20@100\nf.mp4\n#EXT-X-BYTERANGE:30\nf.mp4"+ending);
 check(p.segments.size()==3);check(p.bytes==150);check(p.segments.get(1).sequence==42);check(p.segments.get(1).iv[15]==42);check(p.segments.get(2).offset==120);check(p.segments.get(1).key.toString().endsWith("/a/key"));check(p.segments.get(0).init);check(p.segments.get(0).key==null);
 p=Mp4Playlist115.parse(base,"#EXTM3U\n#EXT-X-KEY:METHOD=AES-128,URI=\"key\",IV=0x01\na.ts\n#EXT-X-KEY:METHOD=NONE\nb.ts"+ending);check(p.bytes==-1);check(p.segments.get(0).iv[15]==1);check(p.segments.get(1).key==null);
 bad(()->Mp4Playlist115.parse(base,"#EXTM3U\na.ts"));bad(()->Mp4Playlist115.parse(base,"#EXTM3U\n#EXT-X-BYTERANGE:10\na.ts"+ending));bad(()->Mp4Playlist115.parse(base,"#EXTM3U\n#EXT-X-BYTERANGE:10@0\na.ts\n#EXT-X-BYTERANGE:10\nb.ts"+ending));bad(()->Mp4Playlist115.parse(base,"#EXTM3U\n#EXT-X-BYTERANGE:9223372036854775807@1\na.ts"+ending));bad(()->Mp4Playlist115.parse(base,"#EXTM3U\n#EXT-X-KEY:METHOD=SAMPLE-AES,URI=\"key\"\na.ts"+ending));bad(()->Mp4Playlist115.parse(base,"#EXTM3U\n#EXT-X-DISCONTINUITY\na.ts"+ending));bad(()->Mp4Playlist115.parse(base,"#EXTM3U\n#EXT-X-MAP:URI=\"init\"\na.m4s\n#EXT-X-MAP:URI=\"other\"\nb.m4s"+ending));bad(()->Mp4Playlist115.resolve(base,"file:///etc/passwd"));bad(()->Mp4Playlist115.resolve(base,"https://user:secret@example.com/x"));bad(()->Mp4Playlist115.iv("0xwrong",0));check(Mp4Playlist115.iv(null,256)[14]==1);
 String master="#EXTM3U\n#EXT-X-MEDIA:TYPE=AUDIO,GROUP-ID=\"aud\",URI=\"audio.m3u8\"\n#EXT-X-STREAM-INF:BANDWIDTH=100,AUDIO=\"aud\"\nvideo.m3u8\n";List<Mp4Playlist115.Plan> plans=Mp4Playlist115.load(new URL("https://delivery.domand.nicovideo.jp/master.m3u8"),u->u.getPath().contains("master")?master:"#EXTM3U\nx.m4s"+ending);check(plans.size()==2);check(plans.get(0).segments.size()==1);check(Mp4Playlist115.attrs("#EXT-X-MEDIA:NAME=\"a,b\",URI=\"x\"").get("NAME").equals("a,b"));check(!Mp4Playlist115.filename("a/b:c\n", "sm1").contains("/"));check(Mp4Playlist115.filename("", "sm1").endsWith("[sm1].mp4"));System.out.println("Mp4PlaylistTest: "+checks+" checks passed");}
}
